    pattern: "ご注文{ちゅうもん}",
    short: "polite ご",
    explain: "Just as お attaches to native Japanese words to make them polite, ご attaches to words of Chinese origin: ご注文, ご主人, ご家族. Like お, it is used about the listener or a third person and never about yourself, so a waiter asks ご注文は？ and you answer without the ご. There are exceptions worth noticing, such as お電話 and お時間, so it is safest to learn each pair as vocabulary.",
    formation: "ご ＋ N(Sino-Japanese)　（ご注文{ちゅうもん}、ご主人{しゅじん}）　／　お ＋ N(native)　（お名前{なまえ}、お国{くに}）",
