    explain: "This is a flat prohibition and the negative counterpart of 〜てもいいです. It is strong language, so it belongs to someone with the standing to forbid — a teacher, a parent, a notice on a wall — and is almost never aimed at a superior. In everyday conversation a request such as 〜ないでください, which comes in Lesson 17, is often used instead.",
    formation: "Vて ＋ は いけません",
