    explain: "The same 〜て います also covers an action you keep up over a stretch of time: an exercise routine, the job you hold, the goods a shop sells. A time expression such as 毎日 or 毎朝 usually makes the habitual reading clear. Where the plain ます form would state a general fact, 〜て います presents it as your current practice, which is why it is the form you want when describing your life at the moment.",
    formation: "[毎日{まいにち}／毎朝{まいあさ}／毎晩{まいばん}] ＋ Vて います",
