    explain: "With verbs of movement such as 渡ります, 歩きます, 曲がります and 散歩します, を marks the space you move through or along rather than a direct object. Compare で, which marks the place where an action simply happens: 公園で 遊びます is playing in the park, while 公園を 散歩します is walking through it. This を is essential for giving street directions.",
