    pattern: "Xは Yと いう 意味{いみ}です",
    short: "explaining meanings",
    explain: "To explain what a word or a sign means, put it as the topic with は and finish with と いう 意味{いみ}です. The という here is the quotative と plus 言{い}います, so whatever precedes it is treated as language rather than as an object, and it stays in the plain form. To ask for a meaning, use the question word どういう: どういう 意味{いみ}ですか.",
    formation: "X ＋ は ＋ [Y plain form] ＋ と いう 意味{いみ}です　／　どういう 意味{いみ}ですか",
