    explain: "As you saw in Lesson 38, a dictionary-form verb plus の behaves as a noun. Put に after it and you have named a purpose, and the predicate that follows is drawn from a small set: 使{つか}います, 役{やく}に 立{た}ちます, いいです, 便利{べんり}です, 必要{ひつよう}です, いります, ［時間{じかん}が］かかります. A plain noun can stand in the same slot without の. This is the pattern for saying what a tool is for and how much time or money a job swallows.",
